-- WorkSafe asbestos guideline: more sections read 26 Nov 2026 (Framework v0.4, 3.2 and C.2). Updates the one asbestos item added in 20261126010000 and the WSASBG register row. Guarded: runs once.
update public.legal_sources set provisions_read = $q$sections 1, 2.1 to 2.4, 3.3, 3.4, 5.1 to 5.12, 6, 7.3 to 7.5, 7.16, 7.17, 8.1 to 8.6 and glossary entries for PCBU, other persons at the workplace and worker read in full (sections 3.3, 3.4, 5.11, 5.12, 7.3 to 7.5, 7.16 and 8.1 to 8.3 added on 26 Nov 2026); sections 2.5, 3.1, 3.2, 3.5, 3.6, 4, 7.1, 7.2, 7.6 to 7.15 and the appendices not read in full$q$ where key='WSASBG';
update public.compliance_items set legal_basis_detail = replace(legal_basis_detail, 'A marae with no employees is probably', 'Where asbestos is found or assumed it must be clearly indicated, for example by labels, a site plan or an asbestos register. Only a competent person should take samples, and a sample must be analysed at an accredited laboratory. A marae with no employees is probably') where name = $q$Asbestos checked in any building built before 2000, with a management plan if it is present$q$ and legal_basis_detail not like '%clearly indicated%';
